	klimaat_natuur_type_id bigint NOT NULL    -- Nature type inherited from  the climate search area. Together with maintenance type refers to the link table that specifies the allowed maintenance types for the nature type
)
;

ALTER TABLE imna.zoek_gebied_toegestane_beheer_typen_klimaat
    OWNER to anlb;
	
CREATE TABLE IF NOT EXISTS imna.zoek_gebied_toegestane_beheer_typen_landschap
(
	zoek_gebied_landschap_id bigint NOT NULL,    -- ID linking to the landscape search area
	beheer_type_id bigint NOT NULL    -- Domain Id linking to the specific maintenance type of a landscape area
)
;

ALTER TABLE imna.zoek_gebied_toegestane_beheer_typen_landschap
    OWNER to anlb;
	
CREATE TABLE IF NOT EXISTS imna.zoek_gebied_toegestane_beheer_typen_water
(
	zoek_gebied_water_id bigint NOT NULL,    -- ID linking to the water search area
	water_natuur_type_id bigint NOT NULL,    -- Nature type inherited from  the water search area. Together with maintenance type refers to the link table that specifies the allowed maintenance types for the nature type
	beheer_type_id bigint NOT NULL
)
;

ALTER TABLE imna.zoek_gebied_toegestane_beheer_typen_water
    OWNER to anlb;
	
CREATE TABLE IF NOT EXISTS imna.zoek_gebied_water
(
	id bigint NOT NULL   DEFAULT NEXTVAL(('imna_seq'::text)::regclass),    -- Internal ID of the water search area
	identificatie char(100) NOT NULL,    -- External ID of the water search area
	begin_geldigheid timestamp NOT NULL,    -- Start of the validity for this version of the water search area
	eind_geldigheid timestamp NULL,    -- End of the validity for this version of the water search area
	begin_tijd timestamp NULL,    -- Start of the validity for this version of the water search area identified by the idenficatie and provinceId
	eind_tijd timestamp NULL,    -- End of the validity for this version of the water search area identified by the idenficatie and provinceId
	nbp_id bigint NOT NULL,    -- Id linking to the Nature Maintenance Plan use to submit this version of the water search area
	status_id bigint NOT NULL,    -- Domain Id linking to the status of the water search area
	provincie_id bigint NOT NULL,    -- Domain id linking to the province who is responsible for the water search area
	deelgebied_id bigint NULL,    -- Domain id linking to the sub-area that is associated with the water search area. As sub-areas are specified per province the reference is to the link-table.
	geom geometry NOT NULL,    -- Geometry single polygon in EPSG:28992 of the water search area
	water_natuur_type_id bigint NOT NULL,    -- Domain id linking to the water nature type of the water search area
	naam char(100) NULL,    -- name of the water search area
	deel_gebied_naam char(100) NULL    -- DEPRECATED. in 2022 replaced with deelgebied_id
)
;

ALTER TABLE imna.zoek_gebied_water
    OWNER to anlb;

