COMMENT ON TABLE imna.beheer_gebied
	IS 'Maintenance area. Aggregation of all maintenance areas in a plan. Detailed specification of the area is stored in its detailed tables. Attribute gebied_type_id specifies what detail table to use for this maintenance area.'
;

COMMENT ON COLUMN imna.beheer_gebied.id
	IS 'Internal ID of the maintenance area'
;

COMMENT ON COLUMN imna.beheer_gebied.identificatie
	IS 'External ID of the maintenance area'
;

COMMENT ON COLUMN imna.beheer_gebied.begin_geldigheid
	IS 'Start of the validity for this version of the maintenance area'
;

COMMENT ON COLUMN imna.beheer_gebied.eind_geldigheid
	IS 'End of the validity for this version of the maintenance area'
;

COMMENT ON COLUMN imna.beheer_gebied.begin_tijd
	IS 'Start of the validity for this version of the maintenance area identified by the idenficatie and provinceId'
;

COMMENT ON COLUMN imna.beheer_gebied.eind_tijd
	IS 'End of the validity for this version of the maintenance area identified by the idenficatie and provinceId'
;

COMMENT ON COLUMN imna.beheer_gebied.nbp_id
	IS 'Id linking to the Nature Maintenance Plan used to submit this version of the Maintenance area'
;

COMMENT ON COLUMN imna.beheer_gebied.status_id
	IS 'Domain Id linking to the status of the maintenance area'
;

COMMENT ON COLUMN imna.beheer_gebied.provincie_id
	IS 'Domain id linking to the province who is responsible for the maintenance area'
;

COMMENT ON COLUMN imna.beheer_gebied.gebied_type_id
	IS 'Domain id linking to the main type of the maintenance area. This will denote what detail table is attached to this maintenance area.'
;

COMMENT ON COLUMN imna.beheer_gebied.geom
	IS 'Geometry single polygon in EPSG:28992 of the maintenance area'
;

COMMENT ON TABLE imna.beheer_gebied_ambitie
	IS 'Ambition of maintenance area. Aggregation of all ambition areas in a plan. Detailed specification of the area is stored in its detailed tables. Attribute gebied_type_id specifies what detail table to use for this maintenance area.'
;

COMMENT ON COLUMN imna.beheer_gebied_ambitie.id
	IS 'Internal ID of the ambition area'
;

COMMENT ON COLUMN imna.beheer_gebied_ambitie.identificatie
	IS 'External ID of the ambition area'
