	IS 'Start of the validity for this version of the ambition area identified by the idenficatie and provinceId'
;

COMMENT ON COLUMN imna.beheer_gebied_ambitie.eind_tijd
	IS 'End of the validity for this version of the ambition area identified by the idenficatie and provinceId'
;

COMMENT ON COLUMN imna.beheer_gebied_ambitie.nbp_id
	IS 'Id linking to the Nature Maintenance Plan used to submit this version of the ambition area'
;

COMMENT ON COLUMN imna.beheer_gebied_ambitie.status_id
	IS 'Domain Id linking to the status of the ambition area.'
;

COMMENT ON COLUMN imna.beheer_gebied_ambitie.provincie_id
	IS 'Domain id linking to the province who is responsible for the ambition area'
;

COMMENT ON COLUMN imna.beheer_gebied_ambitie.gebied_type_id
	IS 'Domain id linking to the main type of the ambition area. This will denote what detail table is attached to this ambition area.'
;

COMMENT ON COLUMN imna.beheer_gebied_ambitie.status_ehs_id
	IS 'Domain Id linking to the EHS status of the ambition area. EHS (Ecologische hoofd structuur) stands for main ecological structure.'
;

COMMENT ON COLUMN imna.beheer_gebied_ambitie.geom
	IS 'Geometry single polygon in EPSG:28992 of the ambition area'
;

COMMENT ON TABLE imna.beheer_gebied_to_ambities
