COMMENT ON COLUMN imna.beheer_gebied_to_ambities.ambitie_gebied_id
	IS 'ID linking to the ambition area'
;

COMMENT ON TABLE imna.beheer_grootschaligenatuur
	IS 'Detail information of the maintenance area of type G / or large nature.  Large Nature areas are nature areas that have not yet been split in detail. Therefore multiple maintenance types can apply to the area.'
;

COMMENT ON COLUMN imna.beheer_grootschaligenatuur.beheer_gebied_id
	IS 'ID linking to  the internal id of  the maintenance area'
;

COMMENT ON COLUMN imna.beheer_grootschaligenatuur.beheer_type_id
	IS 'Domain Id linking to the main specific maintenance type of the large nature area'
;

COMMENT ON COLUMN imna.beheer_grootschaligenatuur.subsidiabel
	IS 'Specifies if the area can be subsidized'
;

COMMENT ON COLUMN imna.beheer_grootschaligenatuur.voorzieningenbijdrage
	IS 'boolean indicating that additional subsidy is given to maintain facilities for the public visiting the area.'
;

COMMENT ON COLUMN imna.beheer_grootschaligenatuur.toezichtbijdrage
	IS 'boolean indicating that additional subsidy is given to supervise public visiting the area.'
;

COMMENT ON COLUMN imna.beheer_grootschaligenatuur.bijdrage_vaarland
	IS 'boolean indicating that additional subsidy is given to access the maintenance area as it is only reachable by boat'
;

COMMENT ON COLUMN imna.beheer_grootschaligenatuur.bijdrage_gescheperde_schaapskuddes
	IS 'boolean indicating that additional subsidy is given for sheep herding'
;

COMMENT ON COLUMN imna.beheer_grootschaligenatuur.bijdrage_monitoring
	IS 'boolean indicating that additional subsidy is given to monitor the quantity of individual species (flora/fauna) in the maintenance area'
;

COMMENT ON COLUMN imna.beheer_grootschaligenatuur.openstellings_bijdrage_type_id
	IS 'DEPRECATED.  Domain Id linking to the type of allowance that can be received to have the area opened to the public'
;

