/* Create Views */

CREATE OR REPLACE VIEW imna.vm_distinct_year_status AS 
 SELECT DISTINCT natuur_beheer_plan.subsidie_jaar,
    dmn_status_plan.id AS status_id,
    dmn_status_plan.code AS status_code,
    dmn_status_plan.description AS status_desc
   FROM imna.natuur_beheer_plan,
    masterdata.dmn_status_plan
  ORDER BY natuur_beheer_plan.subsidie_jaar;
;

ALTER TABLE imna.vm_distinct_year_status
    OWNER to anlb;

CREATE OR REPLACE VIEW imna.vm_plans_beheer_gebied_ambitie AS 
 SELECT p.id,
    p.begin_geldigheid,
    p.eind_geldigheid,
    p.provincie_id,
    p.subsidie_jaar,
    p.beheer_gebied_ambitie_status_id
   FROM imna.natuur_beheer_plan p
  WHERE ((EXISTS ( SELECT 1
           FROM imna.vm_distinct_year_status d
          WHERE ((p.subsidie_jaar = d.subsidie_jaar) AND (p.beheer_gebied_ambitie_status_id = d.status_id)))) AND (NOT (EXISTS ( SELECT 1
           FROM imna.natuur_beheer_plan p_prev
          WHERE ((p.provincie_id = p_prev.provincie_id) AND (p.subsidie_jaar = p_prev.subsidie_jaar) AND (p.beheer_gebied_ambitie_status_id = p_prev.beheer_gebied_ambitie_status_id) AND (p.begin_geldigheid < p_prev.begin_geldigheid))))));
;

ALTER TABLE imna.vm_plans_beheer_gebied_ambitie
    OWNER to anlb;



CREATE OR REPLACE VIEW imna.vm_plans_beheer_gebied AS 
 SELECT p.id,
    p.begin_geldigheid,
    p.eind_geldigheid,
    p.provincie_id,
    p.subsidie_jaar,
    p.beheer_gebied_status_id
   FROM imna.natuur_beheer_plan p
  WHERE ((EXISTS ( SELECT 1
           FROM imna.vm_distinct_year_status d
          WHERE ((p.subsidie_jaar = d.subsidie_jaar) AND (p.beheer_gebied_status_id = d.status_id)))) AND (NOT (EXISTS ( SELECT 1
           FROM imna.natuur_beheer_plan p_prev
          WHERE ((p.provincie_id = p_prev.provincie_id) AND (p.subsidie_jaar = p_prev.subsidie_jaar) AND (p.beheer_gebied_status_id = p_prev.beheer_gebied_status_id) AND (p.begin_geldigheid < p_prev.begin_geldigheid))))));
;

ALTER TABLE imna.vm_plans_beheer_gebied
    OWNER to anlb;

CREATE OR REPLACE VIEW imna.vm_prov_year_status_beheer_gebied AS 
 SELECT p.subsidie_jaar,
    p.provincie_id,
    p.beheer_gebied_status_id AS status_id,
    b.id AS beheer_gebied_id,
    p.id AS plan_id
   FROM imna.beheer_gebied b,
    imna.vm_plans_beheer_gebied p
  WHERE ((b.provincie_id = p.provincie_id) AND (b.begin_geldigheid <= p.begin_geldigheid) AND (NOT (EXISTS ( SELECT 1
           FROM imna.beheer_gebied b_prev
          WHERE ((b.identificatie = b_prev.identificatie) AND (b.provincie_id = b_prev.provincie_id) AND (p.begin_geldigheid >= b_prev.begin_geldigheid) AND (b.begin_geldigheid < b_prev.begin_geldigheid))))) AND ((b.eind_geldigheid IS NULL) OR (b.eind_geldigheid >= p.eind_geldigheid)));
;

ALTER TABLE imna.vm_prov_year_status_beheer_gebied
    OWNER to anlb;

CREATE OR REPLACE VIEW imna.vm_prov_year_status_beheer_gebied_ambitie AS 
 SELECT p.subsidie_jaar,
    p.provincie_id,
    p.beheer_gebied_ambitie_status_id AS status_id,
    a.id AS ambitie_gebied_id,
    p.id AS plan_id
   FROM imna.beheer_gebied_ambitie a,
    imna.vm_plans_beheer_gebied_ambitie p
  WHERE ((a.provincie_id = p.provincie_id) AND (a.begin_geldigheid <= p.begin_geldigheid) AND (NOT (EXISTS ( SELECT 1
           FROM imna.beheer_gebied_ambitie a_prev
          WHERE (((a.identificatie)::text = (a_prev.identificatie)::text) AND (a.provincie_id = a_prev.provincie_id) AND (p.begin_geldigheid >= a_prev.begin_geldigheid) AND (a.begin_geldigheid < a_prev.begin_geldigheid))))) AND ((a.eind_geldigheid IS NULL) OR (a.eind_geldigheid >= p.eind_geldigheid)));
;

ALTER TABLE imna.vm_prov_year_status_beheer_gebied_ambitie
    OWNER to anlb;
	
	CREATE OR REPLACE VIEW imna.vm_plans_bijzonder_gebied AS 
 SELECT p.id,
    p.begin_geldigheid,
    p.eind_geldigheid,
    p.provincie_id,
    p.subsidie_jaar,
    p.bijzonder_gebied_status_id
   FROM imna.natuur_beheer_plan p
  WHERE ((EXISTS ( SELECT 1
           FROM imna.vm_distinct_year_status d
          WHERE ((p.subsidie_jaar = d.subsidie_jaar) AND (p.bijzonder_gebied_status_id = d.status_id)))) AND (NOT (EXISTS ( SELECT 1
           FROM imna.natuur_beheer_plan p_prev
          WHERE ((p.provincie_id = p_prev.provincie_id) AND (p.subsidie_jaar = p_prev.subsidie_jaar) AND (p.bijzonder_gebied_status_id = p_prev.bijzonder_gebied_status_id) AND (p.begin_geldigheid < p_prev.begin_geldigheid))))));
