CREATE OR REPLACE VIEW imna.v_gs_beheer_gebied AS 
 SELECT ( SELECT btrim((dmn_provincie_code.code)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie,
    ( SELECT btrim((dmn_provincie_code.description)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie_desc,
    s.subsidie_jaar,
    ( SELECT btrim((dmn_status_beheer_gebied.code)::text) AS btrim
           FROM masterdata.dmn_status_beheer_gebied
          WHERE (dmn_status_beheer_gebied.id = s.status_id)) AS status,
    ( SELECT btrim((dmn_status_beheer_gebied.description)::text) AS btrim
           FROM masterdata.dmn_status_beheer_gebied
          WHERE (dmn_status_beheer_gebied.id = s.status_id)) AS status_desc,
    btrim((b.identificatie)::text) AS identificatie,
    b.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    b.begin_tijd,
    b.eind_tijd,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN ( SELECT btrim((dmn_beheer_type_natuur.code)::text) AS btrim
               FROM masterdata.dmn_beheer_type_natuur
              WHERE (dmn_beheer_type_natuur.id = n.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN ( SELECT btrim((dmn_beheer_type_grootschaligenatuur.code)::text) AS btrim
               FROM masterdata.dmn_beheer_type_grootschaligenatuur
              WHERE (dmn_beheer_type_grootschaligenatuur.id = g.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'A'::bpchar))) THEN ( SELECT btrim((dmn_beheer_type_agrarisch.code)::text) AS btrim
               FROM masterdata.dmn_beheer_type_agrarisch
              WHERE (dmn_beheer_type_agrarisch.id = a.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN ( SELECT btrim((dmn_beheer_type_landschap.code)::text) AS btrim
               FROM masterdata.dmn_beheer_type_landschap
              WHERE (dmn_beheer_type_landschap.id = l.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'W'::bpchar))) THEN ( SELECT btrim((dmn_beheer_type_water.code)::text) AS btrim
               FROM masterdata.dmn_beheer_type_water
              WHERE (dmn_beheer_type_water.id = w.beheer_type_id))
            ELSE NULL::text
        END AS beheer_type,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN ( SELECT btrim((dmn_beheer_type_natuur.description)::text) AS btrim
               FROM masterdata.dmn_beheer_type_natuur
              WHERE (dmn_beheer_type_natuur.id = n.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN ( SELECT btrim((dmn_beheer_type_grootschaligenatuur.description)::text) AS btrim
               FROM masterdata.dmn_beheer_type_grootschaligenatuur
              WHERE (dmn_beheer_type_grootschaligenatuur.id = g.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'A'::bpchar))) THEN ( SELECT btrim((dmn_beheer_type_agrarisch.description)::text) AS btrim
               FROM masterdata.dmn_beheer_type_agrarisch
              WHERE (dmn_beheer_type_agrarisch.id = a.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN ( SELECT btrim((dmn_beheer_type_landschap.description)::text) AS btrim
               FROM masterdata.dmn_beheer_type_landschap
              WHERE (dmn_beheer_type_landschap.id = l.beheer_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'W'::bpchar))) THEN ( SELECT btrim((dmn_beheer_type_water.description)::text) AS btrim
               FROM masterdata.dmn_beheer_type_water
              WHERE (dmn_beheer_type_water.id = w.beheer_type_id))
            ELSE NULL::text
        END AS beheer_type_desc,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN
            CASE
                WHEN (n.subsidiabel = true) THEN 'Ja'::text
                WHEN (n.subsidiabel = false) THEN 'Nee'::text
                ELSE NULL::text
            END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN
            CASE
                WHEN (g.subsidiabel = true) THEN 'Ja'::text
                WHEN (g.subsidiabel = false) THEN 'Nee'::text
                ELSE NULL::text
            END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'A'::bpchar))) THEN
            CASE
                WHEN (a.subsidiabel = true) THEN 'Ja'::text
                WHEN (a.subsidiabel = false) THEN 'Nee'::text
                ELSE NULL::text
            END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN
            CASE
                WHEN (l.subsidiabel = true) THEN 'Ja'::text
                WHEN (l.subsidiabel = false) THEN 'Nee'::text
                ELSE NULL::text
            END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'W'::bpchar))) THEN
            CASE
                WHEN (w.subsidiabel = true) THEN 'Ja'::text
                WHEN (w.subsidiabel = false) THEN 'Nee'::text
                ELSE NULL::text
            END
            ELSE NULL::text
        END AS subsidiabel,
		CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN
				CASE
					WHEN (n.voorzieningenbijdrage = true) THEN 'Ja'::text
					WHEN (n.voorzieningenbijdrage = false) THEN 'Nee'::text
					ELSE NULL::text
				END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
									   WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN
				CASE
					WHEN (g.voorzieningenbijdrage = true) THEN 'Ja'::text
					WHEN (g.voorzieningenbijdrage = false) THEN 'Nee'::text
					ELSE NULL::text
				END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN
				CASE
					WHEN (l.voorzieningenbijdrage = true) THEN 'Ja'::text
					WHEN (l.voorzieningenbijdrage = false) THEN 'Nee'::text
					ELSE NULL::text
				END
			ELSE
				NULL::text
        END AS voorzieningenbijdrage,
		CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN
				CASE
					WHEN (n.toezichtbijdrage = true) THEN 'Ja'::text
					WHEN (n.toezichtbijdrage = false) THEN 'Nee'::text
					ELSE NULL::text
				END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
									   WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN
				CASE
					WHEN (g.toezichtbijdrage = true) THEN 'Ja'::text
					WHEN (g.toezichtbijdrage = false) THEN 'Nee'::text
					ELSE NULL::text
				END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN
				CASE
					WHEN (l.toezichtbijdrage = true) THEN 'Ja'::text
					WHEN (l.toezichtbijdrage = false) THEN 'Nee'::text
					ELSE NULL::text
				END
			ELSE
				NULL::text
        END AS toezichtbijdrage,
		CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN
				CASE
					WHEN (n.bijdrage_vaarland = true) THEN 'Ja'::text
					WHEN (n.bijdrage_vaarland = false) THEN 'Nee'::text
					ELSE NULL::text
				END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
									   WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN
				CASE
					WHEN (g.bijdrage_vaarland = true) THEN 'Ja'::text
					WHEN (g.bijdrage_vaarland = false) THEN 'Nee'::text
					ELSE NULL::text
				END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN
				CASE
					WHEN (l.bijdrage_vaarland = true) THEN 'Ja'::text
					WHEN (l.bijdrage_vaarland = false) THEN 'Nee'::text
					ELSE NULL::text
				END
			ELSE
				NULL::text
        END AS bijdrage_vaarland,
		CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN
				CASE
					WHEN (n.bijdrage_gescheperde_schaapskuddes = true) THEN 'Ja'::text
					WHEN (n.bijdrage_gescheperde_schaapskuddes = false) THEN 'Nee'::text
					ELSE NULL::text
				END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
									   WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN
				CASE
					WHEN (g.bijdrage_gescheperde_schaapskuddes = true) THEN 'Ja'::text
					WHEN (g.bijdrage_gescheperde_schaapskuddes = false) THEN 'Nee'::text
					ELSE NULL::text
				END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN
				CASE
					WHEN (l.bijdrage_gescheperde_schaapskuddes = true) THEN 'Ja'::text
					WHEN (l.bijdrage_gescheperde_schaapskuddes = false) THEN 'Nee'::text
					ELSE NULL::text
				END
			ELSE
				NULL::text
        END AS bijdrage_gescheperde_schaapskuddes,
		CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN
				CASE
					WHEN (n.bijdrage_monitoring = true) THEN 'Ja'::text
					WHEN (n.bijdrage_monitoring = false) THEN 'Nee'::text
					ELSE NULL::text
				END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
									   WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN
				CASE
					WHEN (g.bijdrage_monitoring = true) THEN 'Ja'::text
					WHEN (g.bijdrage_monitoring = false) THEN 'Nee'::text
					ELSE NULL::text
				END
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
										 FROM masterdata.dmn_beheergebied_type
										WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN
				CASE
					WHEN (l.bijdrage_monitoring = true) THEN 'Ja'::text
					WHEN (l.bijdrage_monitoring = false) THEN 'Nee'::text
					ELSE NULL::text
				END
			ELSE
				NULL::text
        END AS bijdrage_monitoring,		
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN ( SELECT btrim((dmn_openstellings_bijdrage_type.code)::text) AS btrim
               FROM masterdata.dmn_openstellings_bijdrage_type
              WHERE (dmn_openstellings_bijdrage_type.id = n.openstellings_bijdrage_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN ( SELECT btrim((dmn_openstellings_bijdrage_type.code)::text) AS btrim
               FROM masterdata.dmn_openstellings_bijdrage_type
              WHERE (dmn_openstellings_bijdrage_type.id = g.openstellings_bijdrage_type_id))
            ELSE NULL::text
        END AS openstellings_bijdrage_type,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'N'::bpchar))) THEN ( SELECT btrim((dmn_openstellings_bijdrage_type.description)::text) AS btrim
               FROM masterdata.dmn_openstellings_bijdrage_type
              WHERE (dmn_openstellings_bijdrage_type.id = n.openstellings_bijdrage_type_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN ( SELECT btrim((dmn_openstellings_bijdrage_type.description)::text) AS btrim
               FROM masterdata.dmn_openstellings_bijdrage_type
              WHERE (dmn_openstellings_bijdrage_type.id = g.openstellings_bijdrage_type_id))
            ELSE NULL::text
        END AS openstellings_bijdrage_type_desc,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'G'::bpchar))) THEN ( SELECT string_agg(((((i.percentage || '% '::text) || (d.code)::text) || ': '::text) || (d.description)::text), '<br>'::text ORDER BY d.code) AS string_agg
               FROM (imna.beheer_indicatieve_verhouding_beheer_typen i
                 JOIN masterdata.dmn_beheer_type_natuur d ON ((d.id = i.beheer_type_id)))
              WHERE (i.beheer_gebied_id = g.beheer_gebied_id))
            ELSE NULL::text
        END AS indicatieve_verhouding_beheer_typen,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'A'::bpchar))) THEN ( SELECT string_agg((((d.code)::text || ': '::text) || (d.description)::text), '<br>'::text ORDER BY d.code) AS string_agg
               FROM (imna.beheer_toegestane_beheer_pakketten_agrarisch pak
                 JOIN masterdata.dmn_beheer_pakket d ON ((d.id = pak.beheer_pakket_id)))
              WHERE (pak.beheer_gebied_id = a.beheer_gebied_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN ( SELECT string_agg((((d.code)::text || ': '::text) || (d.description)::text), '<br>'::text ORDER BY d.code) AS string_agg
               FROM (imna.beheer_toegestane_beheer_pakketten_landschap pak
                 JOIN masterdata.dmn_beheer_pakket d ON ((d.id = pak.beheer_pakket_id)))
              WHERE (pak.beheer_gebied_id = l.beheer_gebied_id))
            ELSE NULL::text
        END AS toegestane_beheer_paketten,
        CASE
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'A'::bpchar))) THEN ( SELECT string_agg((((d.code)::text || ': '::text) || (d.description)::text), '<br>'::text ORDER BY d.code) AS string_agg
               FROM (imna.beheer_niet_subsidiabele_beheer_pakketten_agrarisch pak
                 JOIN masterdata.dmn_beheer_pakket d ON ((d.id = pak.beheer_pakket_id)))
              WHERE (pak.beheer_gebied_id = a.beheer_gebied_id))
            WHEN (b.gebied_type_id = ( SELECT dmn_beheergebied_type.id
               FROM masterdata.dmn_beheergebied_type
              WHERE (dmn_beheergebied_type.code = 'L'::bpchar))) THEN ( SELECT string_agg((((d.code)::text || ': '::text) || (d.description)::text), '<br>'::text ORDER BY d.code) AS string_agg
               FROM (imna.beheer_niet_subsidiabele_beheer_pakketten_landschap pak
                 JOIN masterdata.dmn_beheer_pakket d ON ((d.id = pak.beheer_pakket_id)))
              WHERE (pak.beheer_gebied_id = l.beheer_gebied_id))
            ELSE NULL::text
        END AS niet_subsidiabele_beheer_paketten,
    ((( SELECT pr.value
           FROM masterdata.parameters pr
          WHERE ((pr.name)::text = 'GeoWebSNL-NBPGetPublicFileURL'::text)))::text 
		  || s.subsidie_jaar 
		  || '-' || ( SELECT btrim((dmn_status_plan.code)::text) AS btrim
                        FROM masterdata.dmn_status_plan
                       WHERE (dmn_status_plan.id = s.status_id))
		  || '-' || ( SELECT btrim((dmn_provincie_code.code)::text) AS btrim
                        FROM masterdata.dmn_provincie_code
                       WHERE (dmn_provincie_code.id = s.provincie_id))
		  || '-'|| (( SELECT natuur_beheer_plan.document_link
                        FROM imna.natuur_beheer_plan
                       WHERE natuur_beheer_plan.id = s.plan_id)))::text AS document_link,
    b.geom
   FROM ((((((imna.vm_prov_year_status_beheer_gebied s
     JOIN imna.beheer_gebied b ON ((b.id = s.beheer_gebied_id)))
     LEFT JOIN imna.beheer_natuur n ON ((n.beheer_gebied_id = s.beheer_gebied_id)))
     LEFT JOIN imna.beheer_grootschaligenatuur g ON ((g.beheer_gebied_id = s.beheer_gebied_id)))
     LEFT JOIN imna.beheer_agrarisch a ON ((a.beheer_gebied_id = s.beheer_gebied_id)))
     LEFT JOIN imna.beheer_landschap l ON ((l.beheer_gebied_id = s.beheer_gebied_id)))
     LEFT JOIN imna.beheer_water w ON ((w.beheer_gebied_id = s.beheer_gebied_id)));
;

