CREATE OR REPLACE VIEW imna.v_gs_zoek_gebied_agrarisch AS 
 SELECT ( SELECT btrim((dmn_provincie_code.code)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie,
    ( SELECT btrim((dmn_provincie_code.description)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie_desc,
    s.subsidie_jaar,
    ( SELECT btrim((dmn_status_zoek_gebied_agrarisch.code)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_agrarisch
          WHERE (dmn_status_zoek_gebied_agrarisch.id = s.status_id)) AS status,
    ( SELECT btrim((dmn_status_zoek_gebied_agrarisch.description)::text) AS btrim
           FROM masterdata.dmn_status_zoek_gebied_agrarisch
          WHERE (dmn_status_zoek_gebied_agrarisch.id = s.status_id)) AS status_desc,
    a.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    btrim((a.identificatie)::text) AS identificatie,
    a.begin_tijd,
    a.eind_tijd,
    ( SELECT btrim((dmn_natuur_type_agrarisch.code)::text) AS btrim
           FROM masterdata.dmn_natuur_type_agrarisch
          WHERE (dmn_natuur_type_agrarisch.id = a.agrarisch_natuur_type_id)) AS agrarisch_natuur_type,
    ( SELECT btrim((dmn_natuur_type_agrarisch.description)::text) AS btrim
           FROM masterdata.dmn_natuur_type_agrarisch
          WHERE (dmn_natuur_type_agrarisch.id = a.agrarisch_natuur_type_id)) AS agrarisch_natuur_type_desc,
    btrim((a.naam)::text) AS naam,
	CASE
        WHEN (a.deelgebied_id IS NOT NULL) 
			THEN ( SELECT btrim((dmn_deelgebied.code)::text) AS btrim
					 FROM masterdata.dmn_deelgebied
					WHERE (dmn_deelgebied.id = a.deelgebied_id))
			ELSE NULL::text
    END AS deel_gebied_code,
	CASE
        WHEN (a.deelgebied_id IS NOT NULL) 
			THEN ( SELECT btrim((dmn_deelgebied.description)::text) AS btrim
					 FROM masterdata.dmn_deelgebied
					WHERE (dmn_deelgebied.id = a.deelgebied_id))
			ELSE btrim((a.deel_gebied_naam)::text) 
    END AS deel_gebied_naam,
    ( SELECT string_agg((((d.code)::text || ': '::text) || (d.description)::text), '<br>'::text ORDER BY d.code) AS string_agg
           FROM (imna.zoek_gebied_toegestane_beheer_functies_agrarisch fun
             JOIN masterdata.dmn_beheer_functie d ON ((d.id = fun.beheer_functie_id)))
          WHERE (fun.zoek_gebied_agrarisch_id = a.id)) AS toegestane_beheer_functies,
    ( SELECT string_agg((((d.code)::text || ': '::text) || (d.description)::text), '<br>'::text ORDER BY d.code) AS string_agg
           FROM (imna.zoek_gebied_toegestane_beheer_typen_agrarisch typ
             JOIN masterdata.dmn_beheer_type d ON ((d.id = typ.beheer_type_id)))
          WHERE (typ.zoek_gebied_agrarisch_id = a.id)) AS toegestane_beheer_typen,
    ((( SELECT pr.value
           FROM masterdata.parameters pr
          WHERE ((pr.name)::text = 'GeoWebSNL-NBPGetPublicFileURL'::text)))::text 
		  || s.subsidie_jaar 
		  || '-' || ( SELECT btrim((dmn_status_plan.code)::text) AS btrim
                        FROM masterdata.dmn_status_plan
                       WHERE (dmn_status_plan.id = s.status_id))
		  || '-' || ( SELECT btrim((dmn_provincie_code.code)::text) AS btrim
                        FROM masterdata.dmn_provincie_code
                       WHERE (dmn_provincie_code.id = s.provincie_id))
		  || '-'|| (( SELECT natuur_beheer_plan.document_link
                        FROM imna.natuur_beheer_plan
                       WHERE natuur_beheer_plan.id = s.plan_id)))::text AS document_link,
    a.geom
   FROM (imna.vm_prov_year_status_zoek_gebied_agrarisch s
     JOIN imna.zoek_gebied_agrarisch a ON ((a.id = s.zoek_gebied_agrarisch_id)));
;

