CREATE OR REPLACE VIEW imna.v_rvo_bijzonder_gebied AS 
 SELECT ( SELECT dmn_provincie_code.code
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = s.provincie_id)) AS provincie,
    s.subsidie_jaar,
    ( SELECT dmn_status_bijzonder_gebied.code
           FROM masterdata.dmn_status_bijzonder_gebied
          WHERE (dmn_status_bijzonder_gebied.id = s.status_id)) AS status,
    b.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    b.identificatie,
    b.begin_tijd,
    b.eind_tijd,
    ( SELECT dmn_bijzonder_gebied_code.code
           FROM masterdata.dmn_bijzonder_gebied_code
          WHERE (dmn_bijzonder_gebied_code.id = b.gebieds_code_id)) AS gebieds_code,
    b.gebieds_naam,
    b.geom
   FROM (imna.vm_prov_year_status_bijzonder_gebied s
     JOIN imna.bijzonder_gebied b ON ((b.id = s.bijzonder_gebied_id)));
;

ALTER TABLE imna.v_rvo_bijzonder_gebied
    OWNER to anlb;

